window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e3532c1be4c0d5ec"]={"versions": [{"id": "FIG-e3532c1be4c0d5ec", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des AUTOSAR-Basissoftware-Moduls SAE J1939 Transport Layer (<code>J1939Tp</code>) innerhalb des Communication Stacks der AUTOSAR Classic Platform. Das Diagramm modelliert die Interaktionsabfolge beim Empfang segmentierter Nachrichten via Broadcast Announce Message (BAM) zwischen der Hardware-Abstraktionsschicht (<code>CanIf</code>), dem Transport-Layer (<code>J1939Tp</code>) und der Routing-Schicht (<code>PduR</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Komponenten-Lebenslinien (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\">\n<li><code>CanIf</code> (CAN Interface): Untere Schicht, meldet eingehende CAN-Frames an den Transport Layer.</li>\n<li><code>J1939Tp</code> (SAE J1939 Transport Layer): Zentraler Protokollinitiator und Reassemblierungs-Modul.</li>\n<li><code>PduR</code> (PDU Router): Obere Schicht zur PDU-Weiterleitung an Zielmodule/Applikation.</li>\n</ul>\n<p class=\"fig-p\">Beteiligte Schnittstellen und Meldungen:</p>\n<ul class=\"fig-list\">\n<li><code>J1939Tp_RxIndication()</code>: Synchroner Callback-Aufruf von <code>CanIf</code> an <code>J1939Tp</code> mit assoziierten CAN-Frames/Kommentaren <code>TP.CM_BAM</code> bzw. <code>TP.DT</code>.</li>\n<li><code>PduR_J1939TpStartOfReception()</code>: Synchroner Aufruf von <code>J1939Tp</code> an <code>PduR</code> zur Ankündigung und Pufferreservierung.</li>\n<li><code>PduR_J1939TpCopyRxData()</code>: Synchroner Aufruf von <code>J1939Tp</code> an <code>PduR</code> zum Kopieren empfangener Nutzdatenpakete in den Zielpuffer.</li>\n<li><code>PduR_J1939TpRxIndication()</code>: Synchroner Aufruf von <code>J1939Tp</code> an <code>PduR</code> zur Bestätigung des vollständigen Nachrichtenempfangs.</li>\n<li>Assoziierte Protokoll-Frames/Notizen: <code>TP.CM_BAM</code> (Connection Management Broadcast Announce Message) und <code>TP.DT</code> (Data Transfer).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Empfang des Steuerrahmens: <code>CanIf</code> signalisiert den Empfang einer BAM (<code>TP.CM_BAM</code>) via <code>J1939Tp_RxIndication()</code> an <code>J1939Tp</code>.</li>\n<li>Initialisierung des Puffers: Während der Ausführung von <code>J1939Tp_RxIndication()</code> ruft <code>J1939Tp</code> synchron <code>PduR_J1939TpStartOfReception()</code> am <code>PduR</code> auf und erhält eine synchrone Rückmeldung, bevor der Aufruf an <code>CanIf</code> zurückkehrt.</li>\n<li>Paket-Empfangsschleife (<code>loop for Each Packet</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für jedes Datenpaket (<code>TP.DT</code>) ruft <code>CanIf</code> <code>J1939Tp_RxIndication()</code> auf.</li>\n<li><code>J1939Tp</code> leitet die Nutzdaten synchron mittels <code>PduR_J1939TpCopyRxData()</code> an <code>PduR</code> weiter und wartet auf Rückkehr.</li>\n<li>Optionaler Block (<code>opt Last Packet [YES]</code>): Handelt es sich um das letzte Datenpaket der BAM-Sequenz, ruft <code>J1939Tp</code> synchron <code>PduR_J1939TpRxIndication()</code> am <code>PduR</code> auf, um den erfolgreichen Gesamtempfang anzuzeigen.</li>\n<li>Der initiale Aufruf von <code>J1939Tp_RxIndication()</code> an <code>CanIf</code> wird nach Abarbeitung des jeweiligen Datenpakets mit Rückgabe beendet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm definiert das verbindliche Zusammenspiel der AUTOSAR-Standard-APIs für den verbindungsbehafteten BAM-Empfang gemäß SAE J1939-21 über AUTOSAR BSW. Wesentliche Anforderungen:</p>\n<ul class=\"fig-list\">\n<li><code>PduR_J1939TpStartOfReception()</code> muss zwingend im Kontext des ersten Empfangsaufrufs (<code>TP.CM_BAM</code>) erfolgen.</li>\n<li>Datenpakete (<code>TP.DT</code>) müssen sequenziell per <code>PduR_J1939TpCopyRxData()</code> in den Zielpuffer übertragen werden.</li>\n<li>Die Benachrichtigung über das Nachrichtenende (<code>PduR_J1939TpRxIndication()</code>) erfolgt im Ausführungskontext der <code>J1939Tp_RxIndication()</code> des letzten empfangenen Pakets, bevor der Kontrollfluss an <code>CanIf</code> zurückgegeben wird.</li>\n</ul>"}, {"id": "FIG-5e3e4430d07ddcc0", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des AUTOSAR-Basissoftware-Moduls SAE J1939 Transport Layer (<code>J1939Tp</code>) innerhalb des Communication Stacks der AUTOSAR Classic Platform. Das Diagramm modelliert die Interaktionsabfolge beim Empfang segmentierter Nachrichten via Broadcast Announce Message (BAM) zwischen der Hardware-Abstraktionsschicht (<code>CanIf</code>), dem Transport-Layer (<code>J1939Tp</code>) und der Routing-Schicht (<code>PduR</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Komponenten-Lebenslinien (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\">\n<li><code>CanIf</code> (CAN Interface): Untere Schicht, meldet eingehende CAN-Frames an den Transport Layer.</li>\n<li><code>J1939Tp</code> (SAE J1939 Transport Layer): Zentraler Protokollinitiator und Reassemblierungs-Modul.</li>\n<li><code>PduR</code> (PDU Router): Obere Schicht zur PDU-Weiterleitung an Zielmodule/Applikation.</li>\n</ul>\n<p class=\"fig-p\">Beteiligte Schnittstellen und Meldungen:</p>\n<ul class=\"fig-list\">\n<li><code>J1939Tp_RxIndication()</code>: Synchroner Callback-Aufruf von <code>CanIf</code> an <code>J1939Tp</code> mit assoziierten CAN-Frames/Kommentaren <code>TP.CM_BAM</code> bzw. <code>TP.DT</code>.</li>\n<li><code>PduR_J1939TpStartOfReception()</code>: Synchroner Aufruf von <code>J1939Tp</code> an <code>PduR</code> zur Ankündigung und Pufferreservierung.</li>\n<li><code>PduR_J1939TpCopyRxData()</code>: Synchroner Aufruf von <code>J1939Tp</code> an <code>PduR</code> zum Kopieren empfangener Nutzdatenpakete in den Zielpuffer.</li>\n<li><code>PduR_J1939TpRxIndication()</code>: Synchroner Aufruf von <code>J1939Tp</code> an <code>PduR</code> zur Bestätigung des vollständigen Nachrichtenempfangs.</li>\n<li>Assoziierte Protokoll-Frames/Notizen: <code>TP.CM_BAM</code> (Connection Management Broadcast Announce Message) und <code>TP.DT</code> (Data Transfer).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Empfang des Steuerrahmens: <code>CanIf</code> signalisiert den Empfang einer BAM (<code>TP.CM_BAM</code>) via <code>J1939Tp_RxIndication()</code> an <code>J1939Tp</code>.</li>\n<li>Initialisierung des Puffers: Während der Ausführung von <code>J1939Tp_RxIndication()</code> ruft <code>J1939Tp</code> synchron <code>PduR_J1939TpStartOfReception()</code> am <code>PduR</code> auf und erhält eine synchrone Rückmeldung, bevor der Aufruf an <code>CanIf</code> zurückkehrt.</li>\n<li>Paket-Empfangsschleife (<code>loop for Each Packet</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für jedes Datenpaket (<code>TP.DT</code>) ruft <code>CanIf</code> <code>J1939Tp_RxIndication()</code> auf.</li>\n<li><code>J1939Tp</code> leitet die Nutzdaten synchron mittels <code>PduR_J1939TpCopyRxData()</code> an <code>PduR</code> weiter und wartet auf Rückkehr.</li>\n<li>Optionaler Block (<code>opt Last Packet [YES]</code>): Handelt es sich um das letzte Datenpaket der BAM-Sequenz, ruft <code>J1939Tp</code> synchron <code>PduR_J1939TpRxIndication()</code> am <code>PduR</code> auf, um den erfolgreichen Gesamtempfang anzuzeigen.</li>\n<li>Der initiale Aufruf von <code>J1939Tp_RxIndication()</code> an <code>CanIf</code> wird nach Abarbeitung des jeweiligen Datenpakets mit Rückgabe beendet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm definiert das verbindliche Zusammenspiel der AUTOSAR-Standard-APIs für den verbindungsbehafteten BAM-Empfang gemäß SAE J1939-21 über AUTOSAR BSW. Wesentliche Anforderungen:</p>\n<ul class=\"fig-list\">\n<li><code>PduR_J1939TpStartOfReception()</code> muss zwingend im Kontext des ersten Empfangsaufrufs (<code>TP.CM_BAM</code>) erfolgen.</li>\n<li>Datenpakete (<code>TP.DT</code>) müssen sequenziell per <code>PduR_J1939TpCopyRxData()</code> in den Zielpuffer übertragen werden.</li>\n<li>Die Benachrichtigung über das Nachrichtenende (<code>PduR_J1939TpRxIndication()</code>) erfolgt im Ausführungskontext der <code>J1939Tp_RxIndication()</code> des letzten empfangenen Pakets, bevor der Kontrollfluss an <code>CanIf</code> zurückgegeben wird.</li>\n</ul>"}, {"id": "FIG-4f2975e78098caa3", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des AUTOSAR-Basissoftware-Moduls SAE J1939 Transport Layer (<code>J1939Tp</code>) innerhalb des Communication Stacks der AUTOSAR Classic Platform. Das Diagramm modelliert die Interaktionsabfolge beim Empfang segmentierter Nachrichten via Broadcast Announce Message (BAM) zwischen der Hardware-Abstraktionsschicht (<code>CanIf</code>), dem Transport-Layer (<code>J1939Tp</code>) und der Routing-Schicht (<code>PduR</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Komponenten-Lebenslinien (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\">\n<li><code>CanIf</code> (CAN Interface): Untere Schicht, meldet eingehende CAN-Frames an den Transport Layer.</li>\n<li><code>J1939Tp</code> (SAE J1939 Transport Layer): Zentraler Protokollinitiator und Reassemblierungs-Modul.</li>\n<li><code>PduR</code> (PDU Router): Obere Schicht zur PDU-Weiterleitung an Zielmodule/Applikation.</li>\n</ul>\n<p class=\"fig-p\">Beteiligte Schnittstellen und Meldungen:</p>\n<ul class=\"fig-list\">\n<li><code>J1939Tp_RxIndication()</code>: Synchroner Callback-Aufruf von <code>CanIf</code> an <code>J1939Tp</code> mit assoziierten CAN-Frames/Kommentaren <code>TP.CM_BAM</code> bzw. <code>TP.DT</code>.</li>\n<li><code>PduR_J1939TpStartOfReception()</code>: Synchroner Aufruf von <code>J1939Tp</code> an <code>PduR</code> zur Ankündigung und Pufferreservierung.</li>\n<li><code>PduR_J1939TpCopyRxData()</code>: Synchroner Aufruf von <code>J1939Tp</code> an <code>PduR</code> zum Kopieren empfangener Nutzdatenpakete in den Zielpuffer.</li>\n<li><code>PduR_J1939TpRxIndication()</code>: Synchroner Aufruf von <code>J1939Tp</code> an <code>PduR</code> zur Bestätigung des vollständigen Nachrichtenempfangs.</li>\n<li>Assoziierte Protokoll-Frames/Notizen: <code>TP.CM_BAM</code> (Connection Management Broadcast Announce Message) und <code>TP.DT</code> (Data Transfer).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Empfang des Steuerrahmens: <code>CanIf</code> signalisiert den Empfang einer BAM (<code>TP.CM_BAM</code>) via <code>J1939Tp_RxIndication()</code> an <code>J1939Tp</code>.</li>\n<li>Initialisierung des Puffers: Während der Ausführung von <code>J1939Tp_RxIndication()</code> ruft <code>J1939Tp</code> synchron <code>PduR_J1939TpStartOfReception()</code> am <code>PduR</code> auf und erhält eine synchrone Rückmeldung, bevor der Aufruf an <code>CanIf</code> zurückkehrt.</li>\n<li>Paket-Empfangsschleife (<code>loop for Each Packet</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für jedes Datenpaket (<code>TP.DT</code>) ruft <code>CanIf</code> <code>J1939Tp_RxIndication()</code> auf.</li>\n<li><code>J1939Tp</code> leitet die Nutzdaten synchron mittels <code>PduR_J1939TpCopyRxData()</code> an <code>PduR</code> weiter und wartet auf Rückkehr.</li>\n<li>Optionaler Block (<code>opt Last Packet [YES]</code>): Handelt es sich um das letzte Datenpaket der BAM-Sequenz, ruft <code>J1939Tp</code> synchron <code>PduR_J1939TpRxIndication()</code> am <code>PduR</code> auf, um den erfolgreichen Gesamtempfang anzuzeigen.</li>\n<li>Der initiale Aufruf von <code>J1939Tp_RxIndication()</code> an <code>CanIf</code> wird nach Abarbeitung des jeweiligen Datenpakets mit Rückgabe beendet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm definiert das verbindliche Zusammenspiel der AUTOSAR-Standard-APIs für den verbindungsbehafteten BAM-Empfang gemäß SAE J1939-21 über AUTOSAR BSW. Wesentliche Anforderungen:</p>\n<ul class=\"fig-list\">\n<li><code>PduR_J1939TpStartOfReception()</code> muss zwingend im Kontext des ersten Empfangsaufrufs (<code>TP.CM_BAM</code>) erfolgen.</li>\n<li>Datenpakete (<code>TP.DT</code>) müssen sequenziell per <code>PduR_J1939TpCopyRxData()</code> in den Zielpuffer übertragen werden.</li>\n<li>Die Benachrichtigung über das Nachrichtenende (<code>PduR_J1939TpRxIndication()</code>) erfolgt im Ausführungskontext der <code>J1939Tp_RxIndication()</code> des letzten empfangenen Pakets, bevor der Kontrollfluss an <code>CanIf</code> zurückgegeben wird.</li>\n</ul>"}, {"id": "FIG-048fcc4304660db2", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des AUTOSAR-Basissoftware-Moduls SAE J1939 Transport Layer (<code>J1939Tp</code>) innerhalb des Communication Stacks der AUTOSAR Classic Platform. Das Diagramm modelliert die Interaktionsabfolge beim Empfang segmentierter Nachrichten via Broadcast Announce Message (BAM) zwischen der Hardware-Abstraktionsschicht (<code>CanIf</code>), dem Transport-Layer (<code>J1939Tp</code>) und der Routing-Schicht (<code>PduR</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Komponenten-Lebenslinien (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\">\n<li><code>CanIf</code> (CAN Interface): Untere Schicht, meldet eingehende CAN-Frames an den Transport Layer.</li>\n<li><code>J1939Tp</code> (SAE J1939 Transport Layer): Zentraler Protokollinitiator und Reassemblierungs-Modul.</li>\n<li><code>PduR</code> (PDU Router): Obere Schicht zur PDU-Weiterleitung an Zielmodule/Applikation.</li>\n</ul>\n<p class=\"fig-p\">Beteiligte Schnittstellen und Meldungen:</p>\n<ul class=\"fig-list\">\n<li><code>J1939Tp_RxIndication()</code>: Synchroner Callback-Aufruf von <code>CanIf</code> an <code>J1939Tp</code> mit assoziierten CAN-Frames/Kommentaren <code>TP.CM_BAM</code> bzw. <code>TP.DT</code>.</li>\n<li><code>PduR_J1939TpStartOfReception()</code>: Synchroner Aufruf von <code>J1939Tp</code> an <code>PduR</code> zur Ankündigung und Pufferreservierung.</li>\n<li><code>PduR_J1939TpCopyRxData()</code>: Synchroner Aufruf von <code>J1939Tp</code> an <code>PduR</code> zum Kopieren empfangener Nutzdatenpakete in den Zielpuffer.</li>\n<li><code>PduR_J1939TpRxIndication()</code>: Synchroner Aufruf von <code>J1939Tp</code> an <code>PduR</code> zur Bestätigung des vollständigen Nachrichtenempfangs.</li>\n<li>Assoziierte Protokoll-Frames/Notizen: <code>TP.CM_BAM</code> (Connection Management Broadcast Announce Message) und <code>TP.DT</code> (Data Transfer).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Empfang des Steuerrahmens: <code>CanIf</code> signalisiert den Empfang einer BAM (<code>TP.CM_BAM</code>) via <code>J1939Tp_RxIndication()</code> an <code>J1939Tp</code>.</li>\n<li>Initialisierung des Puffers: Während der Ausführung von <code>J1939Tp_RxIndication()</code> ruft <code>J1939Tp</code> synchron <code>PduR_J1939TpStartOfReception()</code> am <code>PduR</code> auf und erhält eine synchrone Rückmeldung, bevor der Aufruf an <code>CanIf</code> zurückkehrt.</li>\n<li>Paket-Empfangsschleife (<code>loop for Each Packet</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für jedes Datenpaket (<code>TP.DT</code>) ruft <code>CanIf</code> <code>J1939Tp_RxIndication()</code> auf.</li>\n<li><code>J1939Tp</code> leitet die Nutzdaten synchron mittels <code>PduR_J1939TpCopyRxData()</code> an <code>PduR</code> weiter und wartet auf Rückkehr.</li>\n<li>Optionaler Block (<code>opt Last Packet [YES]</code>): Handelt es sich um das letzte Datenpaket der BAM-Sequenz, ruft <code>J1939Tp</code> synchron <code>PduR_J1939TpRxIndication()</code> am <code>PduR</code> auf, um den erfolgreichen Gesamtempfang anzuzeigen.</li>\n<li>Der initiale Aufruf von <code>J1939Tp_RxIndication()</code> an <code>CanIf</code> wird nach Abarbeitung des jeweiligen Datenpakets mit Rückgabe beendet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm definiert das verbindliche Zusammenspiel der AUTOSAR-Standard-APIs für den verbindungsbehafteten BAM-Empfang gemäß SAE J1939-21 über AUTOSAR BSW. Wesentliche Anforderungen:</p>\n<ul class=\"fig-list\">\n<li><code>PduR_J1939TpStartOfReception()</code> muss zwingend im Kontext des ersten Empfangsaufrufs (<code>TP.CM_BAM</code>) erfolgen.</li>\n<li>Datenpakete (<code>TP.DT</code>) müssen sequenziell per <code>PduR_J1939TpCopyRxData()</code> in den Zielpuffer übertragen werden.</li>\n<li>Die Benachrichtigung über das Nachrichtenende (<code>PduR_J1939TpRxIndication()</code>) erfolgt im Ausführungskontext der <code>J1939Tp_RxIndication()</code> des letzten empfangenen Pakets, bevor der Kontrollfluss an <code>CanIf</code> zurückgegeben wird.</li>\n</ul>"}, {"id": "FIG-ab6daa020aab9bf6", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des AUTOSAR-Basissoftware-Moduls SAE J1939 Transport Layer (<code>J1939Tp</code>) innerhalb des Communication Stacks der AUTOSAR Classic Platform. Das Diagramm modelliert die Interaktionsabfolge beim Empfang segmentierter Nachrichten via Broadcast Announce Message (BAM) zwischen der Hardware-Abstraktionsschicht (<code>CanIf</code>), dem Transport-Layer (<code>J1939Tp</code>) und der Routing-Schicht (<code>PduR</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Komponenten-Lebenslinien (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\">\n<li><code>CanIf</code> (CAN Interface): Untere Schicht, meldet eingehende CAN-Frames an den Transport Layer.</li>\n<li><code>J1939Tp</code> (SAE J1939 Transport Layer): Zentraler Protokollinitiator und Reassemblierungs-Modul.</li>\n<li><code>PduR</code> (PDU Router): Obere Schicht zur PDU-Weiterleitung an Zielmodule/Applikation.</li>\n</ul>\n<p class=\"fig-p\">Beteiligte Schnittstellen und Meldungen:</p>\n<ul class=\"fig-list\">\n<li><code>J1939Tp_RxIndication()</code>: Synchroner Callback-Aufruf von <code>CanIf</code> an <code>J1939Tp</code> mit assoziierten CAN-Frames/Kommentaren <code>TP.CM_BAM</code> bzw. <code>TP.DT</code>.</li>\n<li><code>PduR_J1939TpStartOfReception()</code>: Synchroner Aufruf von <code>J1939Tp</code> an <code>PduR</code> zur Ankündigung und Pufferreservierung.</li>\n<li><code>PduR_J1939TpCopyRxData()</code>: Synchroner Aufruf von <code>J1939Tp</code> an <code>PduR</code> zum Kopieren empfangener Nutzdatenpakete in den Zielpuffer.</li>\n<li><code>PduR_J1939TpRxIndication()</code>: Synchroner Aufruf von <code>J1939Tp</code> an <code>PduR</code> zur Bestätigung des vollständigen Nachrichtenempfangs.</li>\n<li>Assoziierte Protokoll-Frames/Notizen: <code>TP.CM_BAM</code> (Connection Management Broadcast Announce Message) und <code>TP.DT</code> (Data Transfer).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Empfang des Steuerrahmens: <code>CanIf</code> signalisiert den Empfang einer BAM (<code>TP.CM_BAM</code>) via <code>J1939Tp_RxIndication()</code> an <code>J1939Tp</code>.</li>\n<li>Initialisierung des Puffers: Während der Ausführung von <code>J1939Tp_RxIndication()</code> ruft <code>J1939Tp</code> synchron <code>PduR_J1939TpStartOfReception()</code> am <code>PduR</code> auf und erhält eine synchrone Rückmeldung, bevor der Aufruf an <code>CanIf</code> zurückkehrt.</li>\n<li>Paket-Empfangsschleife (<code>loop for Each Packet</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für jedes Datenpaket (<code>TP.DT</code>) ruft <code>CanIf</code> <code>J1939Tp_RxIndication()</code> auf.</li>\n<li><code>J1939Tp</code> leitet die Nutzdaten synchron mittels <code>PduR_J1939TpCopyRxData()</code> an <code>PduR</code> weiter und wartet auf Rückkehr.</li>\n<li>Optionaler Block (<code>opt Last Packet [YES]</code>): Handelt es sich um das letzte Datenpaket der BAM-Sequenz, ruft <code>J1939Tp</code> synchron <code>PduR_J1939TpRxIndication()</code> am <code>PduR</code> auf, um den erfolgreichen Gesamtempfang anzuzeigen.</li>\n<li>Der initiale Aufruf von <code>J1939Tp_RxIndication()</code> an <code>CanIf</code> wird nach Abarbeitung des jeweiligen Datenpakets mit Rückgabe beendet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm definiert das verbindliche Zusammenspiel der AUTOSAR-Standard-APIs für den verbindungsbehafteten BAM-Empfang gemäß SAE J1939-21 über AUTOSAR BSW. Wesentliche Anforderungen:</p>\n<ul class=\"fig-list\">\n<li><code>PduR_J1939TpStartOfReception()</code> muss zwingend im Kontext des ersten Empfangsaufrufs (<code>TP.CM_BAM</code>) erfolgen.</li>\n<li>Datenpakete (<code>TP.DT</code>) müssen sequenziell per <code>PduR_J1939TpCopyRxData()</code> in den Zielpuffer übertragen werden.</li>\n<li>Die Benachrichtigung über das Nachrichtenende (<code>PduR_J1939TpRxIndication()</code>) erfolgt im Ausführungskontext der <code>J1939Tp_RxIndication()</code> des letzten empfangenen Pakets, bevor der Kontrollfluss an <code>CanIf</code> zurückgegeben wird.</li>\n</ul>"}], "trans": [{"from": "FIG-e3532c1be4c0d5ec", "to": "FIG-5e3e4430d07ddcc0", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5e3e4430d07ddcc0", "to": "FIG-4f2975e78098caa3", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4f2975e78098caa3", "to": "FIG-048fcc4304660db2", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-048fcc4304660db2", "to": "FIG-ab6daa020aab9bf6", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
